import sys
from z3 import *

def solve_sgp(g, s, w):
    # g groups, s size, w weeks
    v = g * s

    # X[week][golfer] = group
    X = [[Int(f"x_{i}_{j}") for j in range(v)] for i in range(w)]

    solver = Solver()

    # Domain constraints
    for i in range(w):
        for j in range(v):
            solver.add(X[i][j] >= 0, X[i][j] < g)

    # Group size constraints
    for i in range(w):
        for k in range(g):
            # Exactly s golfers in group k
            solver.add(PbEq([(X[i][j] == k, 1) for j in range(v)], s))

    # No pair in same group more than once
    for j1 in range(v):
        for j2 in range(j1 + 1, v):
            # Sum of (X[i][j1] == X[i][j2]) <= 1
            solver.add(PbLe([(X[i][j1] == X[i][j2], 1) for i in range(w)], 1))

    # Symmetry breaking
    # Week 0: golfer j is in group j // s
    for j in range(v):
        solver.add(X[0][j] == j // s)

    # Golfer 0 is always in group 0
    for i in range(1, w):
        solver.add(X[i][0] == 0)

    # Order groups in week i by the first element
    # Actually, just order the first elements of each group

    solver.set("timeout", 30000)
    if solver.check() == sat:
        m = solver.model()
        res = []
        for i in range(w):
            for j in range(v):
                res.append(m.evaluate(X[i][j]).as_long())
        print("SAT")
        print(res)
    else:
        print("UNSAT or TIMEOUT")

solve_sgp(10, 3, 8)

def verify(res, w, v, g, s):
    if len(res) != w * v:
        return False, "Length mismatch"

    # Check group sizes
    for i in range(w):
        counts = [0] * g
        for j in range(v):
            counts[res[i * v + j]] += 1
        if any(c != s for c in counts):
            return False, f"Group size mismatch in week {i}: {counts}"

    # Check pairs
    pairs = set()
    for i in range(w):
        groups = [[] for _ in range(g)]
        for j in range(v):
            groups[res[i * v + j]].append(j)

        for k in range(g):
            group = groups[k]
            for idx1 in range(len(group)):
                for idx2 in range(idx1 + 1, len(group)):
                    p = tuple(sorted([group[idx1], group[idx2]]))
                    if p in pairs:
                        return False, f"Pair {p} repeated in week {i}"
                    pairs.add(p)

    return True, "Valid"

